```python
def parse_roman(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if not s:
        raise ValueError('empty string')
    total = 0
    prev_value = 0
    for ch in reversed(s):
        if ch not in values:
            raise ValueError('invalid symbol')
        curr_value = values[ch]
        if curr_value < prev_value:
            total -= curr_value
        else:
            total += curr_value
        prev_value = curr_value
    # Validate that the input is a valid Roman numeral
    # Convert back to Roman numeral and compare with input
    def int_to_roman(num):
        val = [
            1000, 900, 500, 400,
            100, 90, 50, 40,
            10, 9, 5, 4,
            1
        ]
        syms = [
            "M", "CM", "D", "CD",
            "C", "XC", "L", "XL",
            "X", "IX", "V", "IV",
            "I"
        ]
        roman_num = ''
        i = 0
        while num > 0:
            for _ in range(num // val[i]):
                roman_num += syms[i]
                num -= val[i]
            i += 1
        return roman_num

    if s != int_to_roman(total):
        raise ValueError('invalid roman numeral')
    return total
